// Loomy 官方图标（256×256 PNG，内嵌 base64）
//
// 来源：Loomy 客户端资源 `resources/app.ico` 里最大的一档（256×256 / 32bpp）。
// 该 ICO 的每一条都是 **未压缩的 BMP（DIB）**，不是 PNG 压缩项，
// 所以不能直接按 PNG 切出来 —— 需按 BITMAPINFOHEADER + 自下而上的 BGRA
// 逐行解码，再重新编码为 PNG。现值就是这样得到的，未做任何缩放或调色。
//
// ⚠ magpie 只**存**不拉：外部 URL 图标在 git 源安装下不渲染，所以内嵌。
//   256 档是为了高分屏不糊（之前用的那张只有 128，放大会虚）。

export const ICON =
  "data:image/png;base64,"
